int main(void) {
    struct Counter { int value; };
    return 0;
}

exercises.solution:
#include <stdio.h>

int main(void) {
    struct Counter { int value; };
    struct Counter c = {0};
    c.value += 5;
    printf("%d\n", c.value);
    return 0;
}
